import {image,makeCanvas,toBlob} from './core.js';
export function deskewAngle(canvas,details=false){
 const sample=makeCanvas(canvas.width*Math.min(1,600/canvas.width),canvas.height*Math.min(1,600/canvas.width)),ctx=sample.getContext('2d');ctx.drawImage(canvas,0,0,sample.width,sample.height);const bytes=ctx.getImageData(0,0,sample.width,sample.height).data,points=[],stride=sample.width+1,integral=new Float64Array(stride*(sample.height+1));for(let y=0;y<sample.height;y++){let sum=0;for(let x=0;x<sample.width;x++){sum+=bytes[(y*sample.width+x)*4];integral[(y+1)*stride+x+1]=integral[y*stride+x+1]+sum;}}const ink=(x,y)=>{const x0=Math.max(0,x-12),x1=Math.min(sample.width,x+13),y0=Math.max(0,y-12),y1=Math.min(sample.height,y+13),mean=(integral[y1*stride+x1]-integral[y0*stride+x1]-integral[y1*stride+x0]+integral[y0*stride+x0])/((x1-x0)*(y1-y0));return bytes[(y*sample.width+x)*4]<mean-18;};
 for(let y=0;y<sample.height;y++)for(let x=0;x<sample.width;x+=2)if(ink(x,y))points.push([x-sample.width/2,y-sample.height/2]);
 const coverage=points.length/(sample.width*sample.height/2);if(coverage<.001||coverage>.3)return details?{coverage,angle:0}:0;
 function score(degrees){const a=degrees*Math.PI/180,s=Math.sin(a),c=Math.cos(a),rows=new Uint32Array(sample.height+160);for(const [x,y]of points){const row=Math.round(x*s+y*c+rows.length/2);if(row>=0&&row<rows.length)rows[row]++;}return rows.reduce((sum,n)=>sum+n*n,0);}
 const baseline=score(0);let best={angle:0,value:baseline};for(let angle=-6;angle<=6;angle+=.5){const value=score(angle);if(value>best.value)best={angle,value};}
 const angle=best.value>baseline*1.05?best.angle*Math.PI/180:0;return details?{coverage,angle,baseline,best}:angle;
}
export async function rotatePrepared(prepared,degrees){
 const angle=((Number(degrees)%360)+360)%360;if(!angle)return prepared;
 const bitmap=await image(prepared.blob),swap=angle===90||angle===270,canvas=makeCanvas(swap?bitmap.height:bitmap.width,swap?bitmap.width:bitmap.height),ctx=canvas.getContext('2d');
 try{ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(angle*Math.PI/180);ctx.drawImage(bitmap,-bitmap.width/2,-bitmap.height/2);return{blob:await toBlob(canvas,'image/png'),transform:{...prepared.transform,width:canvas.width,height:canvas.height,rotationDegrees:angle,baseTransform:prepared.transform}};}finally{bitmap.close();}
}
export function mapWordBox(bbox,transform){
 if(transform.baseTransform){const a=transform.rotationDegrees*Math.PI/180,c=Math.cos(a),s=Math.sin(a),base=transform.baseTransform;const points=[[bbox.x0,bbox.y0],[bbox.x1,bbox.y0],[bbox.x1,bbox.y1],[bbox.x0,bbox.y1]].map(([x,y])=>({x:(x-transform.width/2)*c+(y-transform.height/2)*s+base.width/2,y:-(x-transform.width/2)*s+(y-transform.height/2)*c+base.height/2}));return mapWordBox({x0:Math.min(...points.map(p=>p.x)),y0:Math.min(...points.map(p=>p.y)),x1:Math.max(...points.map(p=>p.x)),y1:Math.max(...points.map(p=>p.y))},base);}
const {scale,angle,width,height,sourceWidth,sourceHeight}=transform,c=Math.cos(angle),s=Math.sin(angle);const points=[[bbox.x0,bbox.y0],[bbox.x1,bbox.y0],[bbox.x1,bbox.y1],[bbox.x0,bbox.y1]].map(([x,y])=>({x:((x-width/2)*c+(y-height/2)*s)/scale+sourceWidth/2,y:(-(x-width/2)*s+(y-height/2)*c)/scale+sourceHeight/2}));return{x0:Math.max(0,Math.min(...points.map(p=>p.x))),y0:Math.max(0,Math.min(...points.map(p=>p.y))),x1:Math.min(sourceWidth,Math.max(...points.map(p=>p.x))),y1:Math.min(sourceHeight,Math.max(...points.map(p=>p.y)))};}
export async function prepareOcr(blob,enabled=true){
 const bitmap=await image(blob),sourceWidth=bitmap.width,sourceHeight=bitmap.height;
 if(!enabled){bitmap.close();return{blob,transform:{scale:1,angle:0,width:sourceWidth,height:sourceHeight,sourceWidth,sourceHeight}};}
 const analysis=makeCanvas(sourceWidth*Math.min(1,700/sourceWidth),sourceHeight*Math.min(1,700/sourceWidth)),analysisContext=analysis.getContext('2d');analysisContext.drawImage(bitmap,0,0,analysis.width,analysis.height);const sample=analysisContext.getImageData(0,0,analysis.width,analysis.height).data,bands=[];let start=-1,gap=0;for(let y=0;y<analysis.height;y++){let dark=0;for(let x=0;x<analysis.width;x++)if(sample[(y*analysis.width+x)*4]<160)dark++;if(dark>analysis.width*.01){if(start<0)start=y;gap=0;}else if(start>=0&&++gap>2){const height=y-gap-start;if(height>3)bands.push(height*sourceWidth/analysis.width);start=-1;}}bands.sort((a,b)=>a-b);const letterHeight=bands[Math.floor(bands.length/2)]||40;const scale=Math.min(letterHeight<35?1.8:1,3000/Math.max(sourceWidth,sourceHeight)),source=makeCanvas(sourceWidth*scale,sourceHeight*scale),ctx=source.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,source.width,source.height);ctx.drawImage(bitmap,0,0,source.width,source.height);bitmap.close();
 const pixels=ctx.getImageData(0,0,source.width,source.height),hist=new Uint32Array(256);for(let i=0;i<pixels.data.length;i+=4){const gray=Math.round(.299*pixels.data[i]+.587*pixels.data[i+1]+.114*pixels.data[i+2]);pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=gray;hist[gray]++;}
 const tile=64,columns=Math.ceil(source.width/tile),rows=Math.ceil(source.height/tile),background=new Float32Array(columns*rows);for(let gy=0;gy<rows;gy++)for(let gx=0;gx<columns;gx++){const bins=new Uint32Array(256);let n=0;for(let y=gy*tile;y<Math.min(source.height,(gy+1)*tile);y+=2)for(let x=gx*tile;x<Math.min(source.width,(gx+1)*tile);x+=2){bins[pixels.data[(y*source.width+x)*4]]++;n++;}let sum=0,white=255;for(let value=0;value<256;value++){sum+=bins[value];if(sum>=n*.9){white=value;break;}}background[gy*columns+gx]=Math.max(50,white);}
 hist.fill(0);for(let y=0;y<source.height;y++)for(let x=0;x<source.width;x++){const px=Math.max(0,Math.min(columns-1,x/tile-.5)),py=Math.max(0,Math.min(rows-1,y/tile-.5)),x0=Math.floor(px),y0=Math.floor(py),x1=Math.min(columns-1,x0+1),y1=Math.min(rows-1,y0+1),fx=px-x0,fy=py-y0,bg=(background[y0*columns+x0]*(1-fx)+background[y0*columns+x1]*fx)*(1-fy)+(background[y1*columns+x0]*(1-fx)+background[y1*columns+x1]*fx)*fy,index=(y*source.width+x)*4,value=Math.round(Math.min(255,pixels.data[index]*255/bg));pixels.data[index]=pixels.data[index+1]=pixels.data[index+2]=value;hist[value]++;}
 const count=source.width*source.height;let total=0,low=0,high=255;for(let i=0;i<256;i++){total+=hist[i];if(total<count*.005)low=i;if(total<count*.99)high=i;}const span=Math.max(40,high-low);
 for(let i=0;i<pixels.data.length;i+=4)pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=Math.max(0,Math.min(255,(pixels.data[i]-low)*255/span));ctx.putImageData(pixels,0,0);
 const angle=deskewAngle(source),c=Math.cos(angle),s=Math.sin(angle),output=makeCanvas(Math.abs(source.width*c)+Math.abs(source.height*s)+40,Math.abs(source.height*c)+Math.abs(source.width*s)+40),out=output.getContext('2d');out.fillStyle='white';out.fillRect(0,0,output.width,output.height);out.translate(output.width/2,output.height/2);out.rotate(angle);out.drawImage(source,-source.width/2,-source.height/2);
 return{blob:await toBlob(output,'image/png'),transform:{scale,angle,width:output.width,height:output.height,sourceWidth,sourceHeight}};
}
